WITH scored AS (SELECT *, NTILE(3) OVER (ORDER BY sqft DESC, id ASC) AS sqft_bucket, LEAD(sqft, 1) OVER (ORDER BY opened_date ASC, id ASC) AS next_sqft, FIRST_VALUE(region) IGNORE NULLS OVER (ORDER BY opened_date ASC, id ASC ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS first_known_region FROM stores WHERE opened_date BETWEEN '2025-08-01' AND '2025-10-01') SELECT id, store_name, city, region, sqft_bucket, next_sqft, first_known_region, CASE WHEN store_name RLIKE '^(Mall Central|Downtown Express)$' THEN 'GROUP_B' ELSE 'GROUP_A' END AS store_name_zone FROM scored ORDER BY store_name_zone DESC
